return ['project-id-version'=>'Google Authenticator 0.58','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/google-authenticator/','po-revision-date'=>'2026-11-26 12:41+0000','last-translator'=>'Kaijia Feng <fengkaijia@gmail.com>','language-team'=>'Chinese (China)','language'=>'zh_CN','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','plural-forms'=>'nplurals=1; plural=0;','x-domain'=>'google-authenticator','messages'=>[' Description that you\'ll see in the Google Authenticator app on your phone.'=>' 在Google Authenticator应用中显示的帐户描述。',' Enabling an App password will decrease your overall login security.'=>' 启用应用专用密码将会在总体上降低登录的安全性。',' Password is not stored in cleartext, this is your only chance to see it.'=>' 密码将不会明文储存，这将是您唯一一次看见密码。',' Relaxed mode allows for more time drifting on your phone clock (&#177;4 min).'=>' 宽松模式允许手机时钟有更大的时间偏差（&#177;4 分钟）。','<strong>ERROR</strong>: Please enter your Google Authenticator code.'=>'<strong>错误</strong>：请输入您的 Google Authenticator 验证码。','<strong>ERROR</strong>: The Google Authenticator code is missing.'=>'<strong>错误</strong>：缺少 Google Authenticator 验证码。','<strong>ERROR</strong>: The Google Authenticator password is incorrect.'=>'<strong>错误</strong>：Google Authenticator 应用专用密码不正确。','<strong>ERROR</strong>: The username, password or Google Authenticator code is incorrect, or the code has expired.'=>'<strong>错误</strong>：用户名、密码或 Google Authenticator 验证码不正确，或验证码已过期。','<strong>ERROR</strong>: Too many incorrect Google Authenticator codes. Please try again in %d minute.'=>'<strong>错误</strong>：Google Authenticator 验证码错误次数过多，请在 %d 分钟后重试。','Active'=>'启用','After adding the site to your authenticator app, type the code it shows here.'=>'在身份验证器应用中添加此站点后，请在此处输入应用显示的验证码。','An account can also be added by typing in the secret. After you\'ve added your account to the App, please type the code you see on the screen into the Authenticator Code field and press the Verify Authenticator Code button.'=>'您也可以手动输入密钥来添加账户。在应用中添加账户后，请将屏幕上显示的验证码输入“身份验证码”字段，然后点击“验证身份验证码”按钮。','Android: Authy'=>'Android: Authy','Android: Google Authenticator'=>'Android: Google Authenticator','Android: Microsoft Authenticator'=>'Android: Microsoft Authenticator','Ask for authenticator code on secondary login screen'=>'在第二个登录页面上要求输入验证码','Authenticator Code'=>'身份验证码','Change network wide Google Authenticator settings'=>'更改全网络的 Google Authenticator 设置','Congratulations, you have successfully enabled Google Authenticator for your account'=>'恭喜，您已为您的账户成功启用 Google Authenticator','Create new password'=>'创建新密码','Create new secret'=>'创建新密钥','Description'=>'描述','Enable App password'=>'启用应用专用密码','Google Authenticator'=>'Google Authenticator','Google Authenticator Settings'=>'Google Authenticator 设置','Google Authenticator code'=>'Google Authenticator验证码','Hide settings from user'=>'不对用户显示设置','If the account setup was successful, you will be logged out, and will need to login again using your Username, Password and Authenticator code generated using the App on your mobile device.'=>'如果账户设置成功，您将被注销，并需要使用用户名、密码以及移动设备上的应用生成的身份验证码重新登录。','If you don\'t have Google Authenticator enabled for your WordPress account, leave this field empty.'=>'如果您的帐号没有启用Google Authenticator身份验证功能，请不必填写此栏。','If you haven\'t already done so, please install an authenticator app on your mobile device, for example:'=>'如果您尚未安装，请在移动设备上安装身份验证器应用，例如：','Log In'=>'登录','Network Settings'=>'网络设置','Network-wide settings in effect, only a super admin can modify them.'=>'全网络设置已生效，只有超级管理员才能修改。','OTP code doesn\'t match supplied secret, please check you\'ve configured Authenticator correctly.'=>'一次性验证码与提供的密钥不匹配，请检查您是否已正确配置身份验证器应用。','Only use network-wide settings, ignoring site settings.'=>'仅使用全网络设置，忽略站点设置。','Please enter the Google Authenticator code using the app on your device.'=>'请输入您设备上的应用显示的 Google Authenticator 验证码。','Relaxed mode'=>'宽松模式','Roles requiring Google Authenticator Enabled'=>'需要启用 Google Authenticator 的角色','Scan this with the Google Authenticator app.'=>'使用Google Authenticator应用扫描此图像。','Secondary Login Screen'=>'第二登录页面','Secret'=>'密钥','Show/Hide QR code'=>'显示/隐藏QR码','Sorry, this role is enabled at the network level and can only be disabled via the <a href="%s">network settings</a>'=>'抱歉，此角色已在网络级别启用，只能通过<a href="%s">网络设置</a>停用','Sorry, you can\'t disable checks for this role as it\'s enabled at the network level.'=>'抱歉，此角色已在网络级别启用，您无法为其停用检查。','Successfully saved your settings for the network'=>'已成功保存网络设置','Successfully saved your settings for the site'=>'已成功保存站点设置','The easiest way to enable your account is to add an account by scanning the QR code using the app.'=>'启用账户最简单的方法是使用应用扫描二维码来添加账户。','Two Screen Signin'=>'分步登录','Verify Authenticator Code'=>'验证身份验证码','iOS: Authy'=>'iOS: Authy','iOS: Google Authenticator'=>'iOS: Google Authenticator','iOS: Microsoft Authenticator'=>'iOS: Microsoft Authenticator']];
